// Unmodified original LedgersBuilder phase after untouched BEAMS; before epilog.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;
public class LedgerRegistrationControlProbe extends LedgerBeamPurgeControlProbe {
 public LedgerRegistrationControlProbe(Book b,SortedSet<Integer> ids){super(b,ids);}
 public void process(){try{
  sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");for(String step:new String[]{"sheet.grid.GridStep","sheet.header.HeadersStep","sheet.stem.StemSeedsStep","sheet.beam.BeamsStep"})call(make(step),"doit",sheet);Class<?> o=Class.forName("org.audiveris.omr.run.Orientation");vertical=o.getField("VERTICAL").get(null);horizontal=o.getField("HORIZONTAL").get(null);Map<?,?> sections=(Map<?,?>)call(make("sheet.ledger.LedgersFilter",sheet),"process");List<String> systems=new ArrayList<>();
  for(Object sys:(List<?>)call(sheet,"getSystems")){system=sys;List<String> staffs=new ArrayList<>();for(Object staff:(List<?>)call(sys,"getStaves")){List<String> lines=new ArrayList<>();for(Object l:(List<?>)call(staff,"getLines")){List<String> p=new ArrayList<>();for(Object pt:(List<?>)get(l,"points"))p.add(StemSeedsProbe.point(pt));lines.add("["+String.join(",",p)+"]");}Object part=call(staff,"getPart");boolean merged=(Boolean)call(part,"isMerged");staffs.add("{\"id\":"+call(staff,"getId")+",\"specific_interline\":"+call(staff,"getSpecificInterline")+",\"lines\":["+String.join(",",lines)+"],\"merged_first\":"+(merged&&call(part,"getFirstStaff")==staff)+",\"merged_last\":"+(merged&&call(part,"getLastStaff")==staff)+",\"tablature\":"+call(staff,"isTablature")+"}");}
   Object builder=make("sheet.ledger.LedgersBuilder",sys);call(builder,"buildLedgers",sections.get(sys));List<?> candidates=(List<?>)get(builder,"ledgerCandidates");Map<?,?> cache=(Map<?,?>)get(builder,"stick2ledger");List<String> cs=new ArrayList<>(),ledgers=new ArrayList<>(),maps=new ArrayList<>();Object old=vertical;vertical=horizontal;try{for(int i=0;i<candidates.size();i++){Object c=candidates.get(i);cs.add(filament(c));Object l=cache.get(c);if(l!=null){Object staff=call(l,"getStaff");ledgers.add("{\"candidate_index\":"+(i+1)+",\"index\":"+call(l,"getIndex")+",\"staff_id\":"+(staff==null?"null":call(staff,"getId"))+",\"bounds\":"+rect(call(l,"getBounds"))+",\"grade\":"+call(l,"getGrade")+",\"removed\":"+call(l,"isRemoved")+",\"glyph\":"+glyph(call(l,"getGlyph"))+"}");}}}finally{vertical=old;}
   for(Object staff:(List<?>)call(sys,"getStaves")){List<String> ls=new ArrayList<>();for(var entry:((Map<?,?>)call(staff,"getLedgerMap")).entrySet()){List<String> cis=new ArrayList<>();for(Object l:(Collection<?>)entry.getValue()){Object stick=((Map<?,?>)get(builder,"ledger2stick")).get(l);cis.add(Integer.toString(candidates.indexOf(stick)+1));}ls.add("{\"index\":"+entry.getKey()+",\"candidate_indices\":["+String.join(",",cis)+"]}");}maps.add("{\"staff_id\":"+call(staff,"getId")+",\"lines\":["+String.join(",",ls)+"]}");}
   systems.add("{\"system_id\":"+call(sys,"getId")+",\"staffs\":["+String.join(",",staffs)+"],\"candidates\":["+String.join(",",cs)+"],\"inters\":["+String.join(",",ledgers)+"],\"staff_maps\":["+String.join(",",maps)+"]}");
  }
  List<String> reductions=new ArrayList<>();Object staff=((List<?>)call(system,"getStaves")).get(0);
  for(double[] grades:new double[][]{{.4,.4,.7},{.7,.4,.4},{.4,.4,.4}})for(int width:new int[]{16,17})for(boolean reverse:new boolean[]{false,true}){
   Object sig=make("sig.SIGraph",system);setField(system,"sig",sig);List<Object> nodes=new ArrayList<>();List<String> records=new ArrayList<>();
   for(int n=0;n<3;n++){Object f=make("glyph.dynamic.StraightFilament",16);call(f,"addSection",ledgerSection(n+1,200,200+8*n,width,1));Object g=call(f,"toGlyph",(Object)null),l=make("sig.inter.LedgerInter",g,Double.valueOf(grades[n]));call(l,"setIndex",1);call(l,"setId",reverse?3-n:n+1);call(sig,"addVertex",l);nodes.add(l);records.add("{\"id\":"+call(l,"getId")+",\"bounds\":"+rect(call(l,"getBounds"))+",\"grade\":"+call(l,"getGrade")+"}");}
   Object builder=make("sheet.ledger.LedgersBuilder",system);var m=builder.getClass().getDeclaredMethod("reduceLedgers",Class.forName("org.audiveris.omr.sheet.Staff"),int.class,List.class);m.setAccessible(true);m.invoke(builder,staff,1,nodes);List<String> kept=new ArrayList<>();for(Object l:nodes)kept.add(call(l,"getId").toString());reductions.add("{\"nodes\":["+String.join(",",records)+"],\"kept_ids\":["+String.join(",",kept)+"]}");
  }
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"reduction_cases\":["+String.join(",",reductions)+"],\"native_outputs_used\":false,\"scope\":\"Untouched original BEAMS and LedgersFilter/LedgersBuilder including acceptance, registration and overlap reduction; before LedgersPostAnalysis epilog.\",\"systems\":["+String.join(",",systems)+"]}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
